'use client';

import { useRef, useState, type ReactNode } from 'react';
import { usePointerDrag } from './use-pointer-drag';
import './drag-to-duplicate-tile.css';

export interface TileKind {
  id: string;
  label: string;
  render: () => ReactNode;
}

export interface PlacedTile {
  key: number;
  kind: string;
  x: number;
  y: number;
}

export interface DragToDuplicateTileProps {
  kinds: TileKind[];
  tiles: PlacedTile[];
  onAdd: (tile: Omit<PlacedTile, 'key'>) => void;
  className?: string;
}

const SIZE = 44;

/**
 * Drag a tile from the palette onto the canvas to drop a copy there; the
 * original stays in the palette for the next copy. Clicking a palette tile
 * (or pressing Enter on it) adds a copy at the next free spot.
 */
export function DragToDuplicateTile({
  kinds,
  tiles,
  onAdd,
  className = '',
}: DragToDuplicateTileProps) {
  const root = useRef<HTMLDivElement>(null);
  const canvas = useRef<HTMLDivElement>(null);
  const [ghost, setGhost] = useState<{
    kind: string;
    x: number;
    y: number;
    over: boolean;
  } | null>(null);
  const dragged = useRef(false);
  const kind = useRef('');

  const toCanvas = (clientX: number, clientY: number) => {
    const rect = canvas.current!.getBoundingClientRect();
    return {
      x: clientX - rect.left - SIZE / 2,
      y: clientY - rect.top - SIZE / 2,
      inside:
        clientX >= rect.left &&
        clientX <= rect.right &&
        clientY >= rect.top &&
        clientY <= rect.bottom,
      w: rect.width,
      h: rect.height,
    };
  };

  const drag = usePointerDrag({
    onStart: (event) => {
      kind.current = (event.currentTarget as HTMLElement).dataset.kind!;
      dragged.current = false;
    },
    onMove: ({ dx, dy, clientX, clientY }) => {
      if (Math.abs(dx) + Math.abs(dy) > 6) dragged.current = true;
      if (!dragged.current) return;
      const r = root.current!.getBoundingClientRect();
      setGhost({
        kind: kind.current,
        x: clientX - r.left - SIZE / 2,
        y: clientY - r.top - SIZE / 2,
        over: toCanvas(clientX, clientY).inside,
      });
    },
    onEnd: ({ clientX, clientY }, cancelled) => {
      setGhost(null);
      if (!dragged.current || cancelled) return;
      const at = toCanvas(clientX, clientY);
      if (at.inside)
        onAdd({
          kind: kind.current,
          x: Math.max(0, Math.min(at.w - SIZE, at.x)),
          y: Math.max(0, Math.min(at.h - SIZE, at.y)),
        });
    },
  });

  const nextSpot = () => {
    const w = canvas.current?.clientWidth ?? 200;
    const perRow = Math.max(1, Math.floor((w - 12) / (SIZE + 8)));
    const i = tiles.length;
    return {
      x: 12 + (i % perRow) * (SIZE + 8),
      y: 12 + Math.floor(i / perRow) * (SIZE + 8),
    };
  };

  const kindOf = (id: string) => kinds.find((k) => k.id === id)!;
  return (
    <div ref={root} className={`mg-dup ${className}`}>
      <div className='mg-dup__palette' role='group' aria-label='Palette'>
        {kinds.map((k) => (
          <button
            key={k.id}
            type='button'
            data-kind={k.id}
            className='mg-dup__source'
            aria-label={`Add ${k.label}`}
            onClick={() => {
              if (dragged.current) {
                dragged.current = false;
                return;
              }
              onAdd({ kind: k.id, ...nextSpot() });
            }}
            {...drag}
          >
            {k.render()}
          </button>
        ))}
      </div>
      <div
        ref={canvas}
        className='mg-dup__canvas'
        data-over={ghost?.over ?? false}
        role='region'
        aria-label={`Canvas, ${tiles.length} ${tiles.length === 1 ? 'tile' : 'tiles'}`}
      >
        {tiles.length === 0 ? (
          <span className='mg-dup__hint'>Drop tiles here</span>
        ) : null}
        {tiles.map((t) => (
          <span
            key={t.key}
            className='mg-dup__tile'
            role='img'
            aria-label={kindOf(t.kind).label}
            style={{ transform: `translate(${t.x}px, ${t.y}px)` }}
          >
            <span className='mg-dup__pop'>{kindOf(t.kind).render()}</span>
          </span>
        ))}
      </div>
      {ghost ? (
        <span
          className='mg-dup__ghost'
          aria-hidden='true'
          style={{ transform: `translate(${ghost.x}px, ${ghost.y}px)` }}
        >
          {kindOf(ghost.kind).render()}
        </span>
      ) : null}
      <p className='mg-dup__status' role='status'>
        {tiles.length} {tiles.length === 1 ? 'tile' : 'tiles'} on the canvas
      </p>
    </div>
  );
}

.mg-dup {
  position: relative;
  display: grid;
  grid-template-columns: 64px 1fr;
  gap: 10px;
  color: var(--mg-ink, #0c1738);
}

.mg-dup__palette {
  display: grid;
  gap: 8px;
  align-content: start;
  padding: 8px;
  border: 1px solid var(--mg-line, #d6def2);
  border-radius: 12px;
  background: var(--mg-foam, #f5f8ff);
}

.mg-dup__source {
  display: grid;
  place-items: center;
  width: 46px;
  height: 46px;
  padding: 0;
  border: 1px solid var(--mg-line-strong, #b9c5e6);
  border-radius: 10px;
  background: #fff;
  cursor: grab;
  touch-action: none;
}

.mg-dup__source:focus-visible {
  outline: 2px solid var(--mg-accent, #164cff);
  outline-offset: 2px;
}

.mg-dup__source svg,
.mg-dup__tile svg,
.mg-dup__ghost svg {
  width: 32px;
  height: 32px;
}

.mg-dup__canvas {
  position: relative;
  min-height: 180px;
  overflow: hidden;
  border: 1px dashed #b9c5e6;
  border-radius: 12px;
  background: #fff;
  transition:
    border-color 150ms ease,
    background-color 150ms ease;
}

.mg-dup__canvas[data-over='true'] {
  border-color: var(--mg-accent, #164cff);
  background: #e6ecff;
}

.mg-dup__hint {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  color: #6b7699;
  font-size: 13px;
}

.mg-dup__tile,
.mg-dup__ghost {
  position: absolute;
  top: 0;
  left: 0;
  display: grid;
  place-items: center;
  width: 44px;
  height: 44px;
}

.mg-dup__pop {
  display: grid;
  animation: mg-dup-in 320ms cubic-bezier(0.3, 1.6, 0.5, 1);
}

.mg-dup__ghost {
  z-index: 5;
  opacity: 0.8;
  pointer-events: none;
  filter: drop-shadow(0 8px 10px rgba(12, 23, 56, 0.35));
}

.mg-dup__status {
  grid-column: 1 / -1;
  margin: 0;
  color: #46527a;
  font-size: 13px;
}

@keyframes mg-dup-in {
  from {
    transform: scale(0.3);
    opacity: 0;
  }
}

@media (prefers-reduced-motion: reduce) {
  .mg-dup__pop {
    animation: none;
  }
  .mg-dup__canvas {
    transition: none;
  }
}

'use client';

import { useRef, type PointerEvent as ReactPointerEvent } from 'react';

export interface DragState {
  /** Distance from where the drag started, in pixels. */
  dx: number;
  dy: number;
  /** Pointer position in viewport coordinates. */
  clientX: number;
  clientY: number;
  /** Smoothed velocity in pixels per millisecond. */
  vx: number;
  vy: number;
}

export interface PointerDragOptions {
  /** Return false to ignore this press. */
  onStart?: (event: ReactPointerEvent<HTMLElement>) => boolean | void;
  onMove?: (drag: DragState) => void;
  /**
   * `cancelled` is true when the browser took the gesture over, for example
   * to scroll the page on touch.
   */
  onEnd?: (drag: DragState, cancelled: boolean) => void;
}

interface Active {
  id: number;
  startX: number;
  startY: number;
  lastX: number;
  lastY: number;
  lastTime: number;
  vx: number;
  vy: number;
}

/**
 * Pointer-capture dragging for mouse, pen and touch. Spread the returned
 * handlers on the element that starts the drag. Pair it with a CSS
 * `touch-action` that leaves the scroll axis you still want to the browser.
 */
export function usePointerDrag(options: PointerDragOptions) {
  const latest = useRef(options);
  latest.current = options;
  const active = useRef<Active | null>(null);

  const snapshot = (a: Active, x: number, y: number): DragState => ({
    dx: x - a.startX,
    dy: y - a.startY,
    clientX: x,
    clientY: y,
    vx: a.vx,
    vy: a.vy,
  });

  const finish = (
    event: ReactPointerEvent<HTMLElement>,
    cancelled: boolean
  ) => {
    const a = active.current;
    if (!a || a.id !== event.pointerId) return;
    active.current = null;
    if (event.currentTarget.hasPointerCapture?.(event.pointerId))
      event.currentTarget.releasePointerCapture(event.pointerId);
    // A pause before release means the pointer was not really flung.
    if (event.timeStamp - a.lastTime > 150) {
      a.vx = 0;
      a.vy = 0;
    }
    latest.current.onEnd?.(
      snapshot(a, event.clientX, event.clientY),
      cancelled
    );
  };

  return {
    onPointerDown(event: ReactPointerEvent<HTMLElement>) {
      if (event.button !== 0 || active.current) return;
      if (latest.current.onStart?.(event) === false) return;
      event.currentTarget.setPointerCapture?.(event.pointerId);
      active.current = {
        id: event.pointerId,
        startX: event.clientX,
        startY: event.clientY,
        lastX: event.clientX,
        lastY: event.clientY,
        lastTime: event.timeStamp,
        vx: 0,
        vy: 0,
      };
    },
    onPointerMove(event: ReactPointerEvent<HTMLElement>) {
      const a = active.current;
      if (!a || a.id !== event.pointerId) return;
      const dt = Math.max(1, event.timeStamp - a.lastTime);
      a.vx = a.vx * 0.6 + ((event.clientX - a.lastX) / dt) * 0.4;
      a.vy = a.vy * 0.6 + ((event.clientY - a.lastY) / dt) * 0.4;
      a.lastX = event.clientX;
      a.lastY = event.clientY;
      a.lastTime = event.timeStamp;
      latest.current.onMove?.(snapshot(a, event.clientX, event.clientY));
    },
    onPointerUp(event: ReactPointerEvent<HTMLElement>) {
      finish(event, false);
    },
    onPointerCancel(event: ReactPointerEvent<HTMLElement>) {
      finish(event, true);
    },
  };
}
